@MainActor func transient_SymbolSolidRect_objectDisplay (
       _ self_x : CanariLength,                          
       _ self_y : CanariLength,                          
       _ self_width : CanariLength,                      
       _ self_height : CanariLength,                     
       _ prefs_symbolColor : NSColor,                    
       _ prefs_symbolDrawingWidthMultipliedByTen : Int
) -> EBShape {
//--- START OF USER ZONE 2
  let r = CanariRect (
    left: self_x,
    bottom: self_y,
    width: self_width,
    height: self_height
  )
  var bp = BezierPath (rect: r)
  bp.lineWidth = CanariLength.pt (prefs_symbolDrawingWidthMultipliedByTen) / 10.0
  bp.lineCapStyle = .round
  var shape = EBShape ()
  shape.add (filled: [bp], prefs_symbolColor)
  return shape
//--- END OF USER ZONE 2
}

